export const WEAPON_PROPERTIES = [{"index":"ammunition","name":"Ammunition","desc":["You can use a weapon that has the ammunition property to make a ranged attack only if you have ammunition to fire from the weapon. Each time you attack with the weapon, you expend one piece of ammunition. Drawing the ammunition from a quiver, case, or other container is part of the attack (you need a free hand to load a one-handed weapon).","At the end of the battle, you can recover half your expended ammunition by taking a minute to search the battlefield. If you use a weapon that has the ammunition property to make a melee attack, you treat the weapon as an improvised weapon (see \"Improvised Weapons\" later in the section). A sling must be loaded to deal any damage when used in this way."],"url":"/api/2014/weapon-properties/ammunition"},{"index":"finesse","name":"Finesse","desc":["When making an attack with a finesse weapon, you use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls."],"url":"/api/2014/weapon-properties/finesse"},{"index":"heavy","name":"Heavy","desc":["Small creatures have disadvantage on attack rolls with heavy weapons. A heavy weapon's size and bulk make it too large for a Small creature to use effectively."],"url":"/api/2014/weapon-properties/heavy"},{"index":"light","name":"Light","desc":["A light weapon is small and easy to handle, making it ideal for use when fighting with two weapons."],"url":"/api/2014/weapon-properties/light"},{"index":"loading","name":"Loading","desc":["Because of the time required to load this weapon, you can fire only one piece of ammunition from it when you use an action, bonus action, or reaction to fire it, regardless of the number of attacks you can normally make."],"url":"/api/2014/weapon-properties/loading"},{"index":"reach","name":"Reach","desc":["This weapon adds 5 feet to your reach when you attack with it, as well as when determining your reach for opportunity attacks with it."],"url":"/api/2014/weapon-properties/reach"},{"index":"special","name":"Special","desc":["A weapon with the special property has unusual rules governing its use, explained in the weapon's description (see \"Special Weapons\" later in this section)."],"url":"/api/2014/weapon-properties/special"},{"index":"thrown","name":"Thrown","desc":["If a weapon has the thrown property, you can throw the weapon to make a ranged attack. If the weapon is a melee weapon, you use the same ability modifier for that attack roll and damage roll that you would use for a melee attack with the weapon. For example, if you throw a handaxe, you use your Strength, but if you throw a dagger, you can use either your Strength or your Dexterity, since the dagger has the finesse property."],"url":"/api/2014/weapon-properties/thrown"},{"index":"two-handed","name":"Two-Handed","desc":["This weapon requires two hands when you attack with it."],"url":"/api/2014/weapon-properties/two-handed"},{"index":"versatile","name":"Versatile","desc":["This weapon can be used with one or two hands. A damage value in parentheses appears with the property--the damage when the weapon is used with two hands to make a melee attack."],"url":"/api/2014/weapon-properties/versatile"},{"index":"monk","name":"Monk","desc":["Monks gain several benefits while unarmed or wielding only monk weapons while they aren't wearing armor or wielding shields."],"url":"/api/2014/weapon-properties/monk"}] as const;

export const MAGIC_SCHOOLS = [{"index":"abjuration","name":"Abjuration","desc":"Abjuration spells are protective in nature, though some of them have aggressive uses. They create magical barriers, negate harmful effects, harm trespassers, or banish creatures to other planes of existence.","url":"/api/2014/magic-schools/abjuration"},{"index":"conjuration","name":"Conjuration","desc":"Conjuration spells involve the transportation of objects and creatures from one location to another. Some spells summon creatures or objects to the caster's side, whereas others allow the caster to teleport to another location. Some conjurations create objects or effects out of nothing.","url":"/api/2014/magic-schools/conjuration"},{"index":"divination","name":"Divination","desc":"Divination spells reveal information, whether in the form of secrets long forgotten, glimpses of the future, the locations of hidden things, the truth behind illusions, or visions of distant people or places.","url":"/api/2014/magic-schools/divination"},{"index":"enchantment","name":"Enchantment","desc":"Enchantment spells affect the minds of others, influencing or controlling their behavior. Such spells can make enemies see the caster as a friend, force creatures to take a course of action, or even control another creature like a puppet.","url":"/api/2014/magic-schools/enchantment"},{"index":"evocation","name":"Evocation","desc":"Evocation spells manipulate magical energy to produce a desired effect. Some call up blasts of fire or lightning. Others channel positive energy to heal wounds.","url":"/api/2014/magic-schools/evocation"},{"index":"illusion","name":"Illusion","desc":"Illusion spells deceive the senses or minds of others. They cause people to see things that are not there, to miss things that are there, to hear phantom noises, or to remember things that never happened. Some illusions create phantom images that any creature can see, but the most insidious illusions plant an image directly in the mind of a creature.","url":"/api/2014/magic-schools/illusion"},{"index":"necromancy","name":"Necromancy","desc":"Necromancy spells manipulate the energies of life and death. Such spells can grant an extra reserve of life force, drain the life energy from another creature, create the undead, or even bring the dead back to life.","url":"/api/2014/magic-schools/necromancy"},{"index":"transmutation","name":"Transmutation","desc":"Transmutation spells change the properties of a creature, object, or environment. They might turn an enemy into a harmless creature, bolster the strength of an ally, make an object move at the caster's command, or enhance a creature's innate healing abilities to rapidly recover from injury.","url":"/api/2014/magic-schools/transmutation"}] as const;

export const ALIGNMENTS = [{"index":"lawful-good","name":"Lawful Good","abbreviation":"LG","desc":"Lawful good (LG) creatures can be counted on to do the right thing as expected by society. Gold dragons, paladins, and most dwarves are lawful good.","url":"/api/2014/alignments/lawful-good"},{"index":"neutral-good","name":"Neutral Good","abbreviation":"NG","desc":"Neutral good (NG) folk do the best they can to help others according to their needs. Many celestials, some cloud giants, and most gnomes are neutral good.","url":"/api/2014/alignments/neutral-good"},{"index":"chaotic-good","name":"Chaotic Good","abbreviation":"CG","desc":"Chaotic good (CG) creatures act as their conscience directs, with little regard for what others expect. Copper dragons, many elves, and unicorns are chaotic good.","url":"/api/2014/alignments/chaotic-good"},{"index":"lawful-neutral","name":"Lawful Neutral","abbreviation":"LN","desc":"Lawful neutral (LN) individuals act in accordance with law, tradition, or personal codes. Many monks and some wizards are lawful neutral.","url":"/api/2014/alignments/lawful-neutral"},{"index":"neutral","name":"Neutral","abbreviation":"N","desc":"Neutral (N) is the alignment of those who prefer to steer clear of moral questions and don't take sides, doing what seems best at the time. Lizardfolk, most druids, and many humans are neutral.","url":"/api/2014/alignments/neutral"},{"index":"chaotic-neutral","name":"Chaotic Neutral","abbreviation":"CN","desc":"Chaotic neutral (CN) creatures follow their whims, holding their personal freedom above all else. Many barbarians and rogues, and some bards, are chaotic neutral.","url":"/api/2014/alignments/chaotic-neutral"},{"index":"lawful-evil","name":"Lawful Evil","abbreviation":"LE","desc":"Lawful evil (LE) creatures methodically take what they want, within the limits of a code of tradition, loyalty, or order. Devils, blue dragons, and hobgoblins are lawful evil.","url":"/api/2014/alignments/lawful-evil"},{"index":"neutral-evil","name":"Neutral Evil","abbreviation":"NE","desc":"Neutral evil (NE) is the alignment of those who do whatever they can get away with, without compassion or qualms. Many drow, some cloud giants, and goblins are neutral evil.","url":"/api/2014/alignments/neutral-evil"},{"index":"chaotic-evil","name":"Chaotic Evil","abbreviation":"CE","desc":"Chaotic evil (CE) creatures act with arbitrary violence, spurred by their greed, hatred, or bloodlust. Demons, red dragons, and orcs are chaotic evil.","url":"/api/2014/alignments/chaotic-evil"}] as const;

export const LANGUAGES = [{"index":"common","name":"Common","type":"Standard","typical_speakers":["Humans"],"script":"Common","url":"/api/2014/languages/common"},{"index":"dwarvish","name":"Dwarvish","desc":"Dwarvish is full of hard consonants and guttural sounds.","type":"Standard","typical_speakers":["Dwarves"],"script":"Dwarvish","url":"/api/2014/languages/dwarvish"},{"index":"elvish","name":"Elvish","desc":"Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires.","type":"Standard","typical_speakers":["Elves"],"script":"Elvish","url":"/api/2014/languages/elvish"},{"index":"giant","name":"Giant","type":"Standard","typical_speakers":["Ogres","Giants"],"script":"Dwarvish","url":"/api/2014/languages/giant"},{"index":"gnomish","name":"Gnomish","desc":"The Gnomish language, which uses the Dwarvish script, is renowned for its technical treatises and its catalogs of knowledge about the natural world.","type":"Standard","typical_speakers":["Gnomes"],"script":"Dwarvish","url":"/api/2014/languages/gnomish"},{"index":"goblin","name":"Goblin","type":"Standard","typical_speakers":["Goblinoids"],"script":"Dwarvish","url":"/api/2014/languages/goblin"},{"index":"halfling","name":"Halfling","desc":"The Halfling language isn't secret, but halflings are loath to share it with others. They write very little, so they don't have a rich body of literature. Their oral tradition, however, is very strong.","type":"Standard","typical_speakers":["Halflings"],"script":"Common","url":"/api/2014/languages/halfling"},{"index":"orc","name":"Orc","desc":"Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script.","type":"Standard","typical_speakers":["Orcs"],"script":"Dwarvish","url":"/api/2014/languages/orc"},{"index":"abyssal","name":"Abyssal","type":"Exotic","typical_speakers":["Demons"],"script":"Infernal","url":"/api/2014/languages/abyssal"},{"index":"celestial","name":"Celestial","type":"Exotic","typical_speakers":["Celestials"],"script":"Celestial","url":"/api/2014/languages/celestial"},{"index":"draconic","name":"Draconic","desc":"Draconic is thought to be one of the oldest languages and is often used in the study of magic. The language sounds harsh to most other creatures and includes numerous hard consonants and sibilants.","type":"Exotic","typical_speakers":["Dragons","Dragonborn"],"script":"Draconic","url":"/api/2014/languages/draconic"},{"index":"deep-speech","name":"Deep Speech","type":"Exotic","typical_speakers":["Aboleths","Cloakers"],"url":"/api/2014/languages/deep-speech"},{"index":"infernal","name":"Infernal","type":"Exotic","typical_speakers":["Devils"],"script":"Infernal","url":"/api/2014/languages/infernal"},{"index":"primordial","name":"Primordial","type":"Exotic","typical_speakers":["Elementals"],"script":"Dwarvish","url":"/api/2014/languages/primordial"},{"index":"sylvan","name":"Sylvan","type":"Exotic","typical_speakers":["Fey creatures"],"script":"Elvish","url":"/api/2014/languages/sylvan"},{"index":"undercommon","name":"Undercommon","type":"Exotic","typical_speakers":["Underdark traders"],"script":"Elvish","url":"/api/2014/languages/undercommon"}] as const;

